import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"招隐士","description":"","frontmatter":{"title":"招隐士","date":"2026-11-24T00:00:00.000Z","seq":30,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"淮南小山","source_book":"楚辞","prev":{"text":"惜誓","link":"/blogs/楚辞/惜誓.html"},"next":{"text":"初放","link":"/blogs/楚辞/初放.html"}},"headers":[],"relativePath":"blogs/楚辞/招隐士.md","filePath":"blogs/楚辞/招隐士.md"}'),o={name:"blogs/楚辞/招隐士.md"};function l(n,a,c,m,r,_){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="招隐士" tabindex="-1">招隐士 <a class="header-anchor" href="#招隐士" aria-label="Permalink to &quot;招隐士&quot;">​</a></h1><p class="poem-meta">先秦 · 淮南小山　·　招隐士</p><div class="poem"><p class="poem-stanza">桂树丛生兮山之幽，偃蹇连蜷兮枝相缭。</p><p class="poem-stanza">山气巄嵷兮石嵯峨，溪谷崭岩兮水曾波。</p><p class="poem-stanza">猿狖群啸兮虎豹嗥，攀援桂枝兮聊淹留。</p><p class="poem-stanza">王孙游兮不归，春草生兮萋萋。</p><p class="poem-stanza">岁暮兮不自聊，蟪蛄鸣兮啾啾。</p><p class="poem-stanza">坱兮轧，山曲岪，心淹留兮恫慌忽。</p><p class="poem-stanza">罔兮沕，憭兮栗，虎豹穴。</p><p class="poem-stanza">丛薄深林兮，人上栗。</p><p class="poem-stanza">嵚岑碕礒兮，碅磳磈硊</p><p class="poem-stanza">树轮相纠兮，林木茷骫。</p><p class="poem-stanza">青莎杂树兮，薠草靃靡</p><p class="poem-stanza">白鹿麏麚兮，或腾或倚。</p><p class="poem-stanza">状貌崟崟兮峨峨，凄凄兮漇漇。</p><p class="poem-stanza">猕猴兮熊罴，慕类兮以悲</p><p class="poem-stanza">攀援桂枝兮聊淹留。</p><p class="poem-stanza">虎豹斗兮熊罴咆，禽兽骇兮亡其曹。</p><p class="poem-stanza">王孙兮归来，山中兮不可以久留。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
